import {AppError,validation} from '@crew/shared';
const types = new Set(['issue','comment','relation','project','label','sprint','attachment','organization','membership','team','invitation','projectGuest']);
const fields = new Set(['id','orgId','projectId','key','title','name','description','body','issueId','sourceIssueId','targetIssueId','kind','direction','statusId','statusName','statusCategory','priority','assigneeId','createdBy','estimate','dueDate','parentId','role','userId','teamId','archived','startDate','endDate','status','completedAt','createdAt','updatedAt','size','sha256']);
export function safeSnapshot(value) {
  if (!value || typeof value !== 'object') return null;
  const result = {};
  for (const [key,item] of Object.entries(value)) {
    if (!fields.has(key)) continue;
    if (item === null || typeof item === 'boolean' || typeof item === 'number') result[key] = item;
    else if (typeof item === 'string') result[key] = item.slice(0,4000);
  }
  if (Array.isArray(value.labels)) result.labels = value.labels.map(label=>({id:label.id,name:label.name,color:label.color}));
  return result;
}
export function publicActivity(row) {
  return {id:row.id,orgId:row.org_id,projectId:row.project_id,actorId:row.actor_id,
    entityType:row.entity_type,entityId:row.entity_id,action:row.action,
    before:row.before_json?JSON.parse(row.before_json):null,
    after:row.after_json?JSON.parse(row.after_json):null,time:row.created_at};
}
export function activitySnapshot(row) {
  const after=row.after_json?JSON.parse(row.after_json):null;
  const before=row.before_json?JSON.parse(row.before_json):null;
  return after??before??{};
}
export function canSeeActivity(ctx,userId,row) {
  if (!ctx.permissions.membership(userId,row.org_id)) return false;
  if(row.entity_type==='relation') {
    const relation=activitySnapshot(row);
    for(const id of [relation.sourceIssueId,relation.targetIssueId]) {
      const issue=ctx.db.prepare('SELECT project_id FROM issues WHERE id=?').get(id);
      if(!issue)return false;
      try {if(!ctx.permissions.canProject(userId,issue.project_id,'insight:read'))return false;}
      catch(error){if(error.code==='NOT_FOUND')return false;throw error;}
    }
  }
  if (row.project_id) {
    try { return ctx.permissions.canProject(userId,row.project_id,'insight:read'); }
    catch (error) { if (error.code === 'NOT_FOUND') return false; throw error; }
  }
  const membership = ctx.permissions.membership(userId,row.org_id);
  return membership.role !== 'guest' && ctx.permissions.canOrg(userId,row.org_id,'insight:read');
}
export function listActivity(ctx,req,query={}) {
  ctx.permissions.scope(req,'insight:read');
  if (!query.orgId) throw validation({orgId:'Choose an organization'});
  ctx.permissions.assertOrg(req,query.orgId,'org:read');
  if (query.projectId) ctx.permissions.assertProject(req,query.projectId,'insight:read');
  if (query.from && !Number.isFinite(Date.parse(query.from))) throw validation({from:'Use an ISO timestamp'});
  if (query.to && !Number.isFinite(Date.parse(query.to))) throw validation({to:'Use an ISO timestamp'});
  const rows = ctx.db.prepare('SELECT * FROM activity WHERE org_id=? ORDER BY created_at DESC,id DESC').all(query.orgId);
  const visible = rows.filter(row=>canSeeActivity(ctx,req.user.id,row))
    .filter(row=>!query.projectId || row.project_id===query.projectId)
    .filter(row=>{
      if(!query.issueId)return true;
      const snapshot=activitySnapshot(row);
      return (row.entity_type==='issue'&&row.entity_id===query.issueId)||snapshot.issueId===query.issueId||
        (row.entity_type==='relation'&&[snapshot.sourceIssueId,snapshot.targetIssueId].includes(query.issueId));
    })
    .filter(row=>!query.userId || row.actor_id===query.userId)
    .filter(row=>!query.entityType || row.entity_type===query.entityType)
    .filter(row=>!query.action || row.action===query.action)
    .filter(row=>!query.from || row.created_at>=query.from)
    .filter(row=>!query.to || row.created_at<=query.to)
    .map(publicActivity);
  return ctx.paginate(visible,query);
}
export function persistActivity(ctx,event) {
  if (!event.orgId || !types.has(event.entityType)) return null;
  const before = safeSnapshot(event.before), after = safeSnapshot(event.after);
  if(event.issueId){if(before)before.issueId=event.issueId;if(after)after.issueId=event.issueId;}
  ctx.db.prepare(`INSERT INTO activity
    (id,org_id,project_id,actor_id,entity_type,entity_id,action,before_json,after_json,created_at)
    VALUES (?,?,?,?,?,?,?,?,?,?)`).run(event.id,event.orgId,event.projectId??null,event.actorId??null,
      event.entityType,event.entityId,event.action,JSON.stringify(before),JSON.stringify(after),event.time);
  return publicActivity(ctx.db.prepare('SELECT * FROM activity WHERE id=?').get(event.id));
}
export function activityById(ctx,id) {
  const row = ctx.db.prepare('SELECT * FROM activity WHERE id=?').get(id);
  if (!row) throw new AppError('NOT_FOUND','Activity not found',404);
  return row;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';
