}
test('parent candidate pages reach beyond 200 and selected lookup resolves independently of search',()=>fixture(async({create,options})=>{
  const first=create({title:'Older than first page'});for(let n=0;n<210;n++)create({title:'Candidate '+n});
  let cursor='',found=false,total=0;
  do{const result=await options('parents','&limit=20'+(cursor?'&cursor='+encodeURIComponent(cursor):''));assert.equal(result.status,200);assert.equal(result.data.total,211);total+=result.data.items.length;found ||= result.data.items.some(item=>item.id===first.id);cursor=result.data.nextCursor;}while(cursor);
  assert.equal(total,211);assert.equal(found,true);
  const selected=await options('parents','&q=does-not-match&id='+first.id);assert.deepEqual(selected.data.items.map(item=>item.id),[first.id]);
}));
test('parent options exclude self and every descendant before matching and pagination',()=>fixture(async({create,options,request,project})=>{
  const root=create({title:'Root'});let node=root;for(let n=0;n<205;n++)node=create({title:'Descendant '+n,parentId:node.id});
  const unrelated=create({title:'Eligible parent'});
  const page=await options('parents','&issueId='+root.id+'&limit=1');assert.deepEqual(page.data.items.map(item=>item.id),[unrelated.id]);assert.equal(page.data.total,1);assert.equal(page.data.nextCursor,null);
  assert.equal((await options('parents','&issueId='+root.id+'&id='+node.id)).data.total,0);
  assert.equal((await request('GET','/projects/'+project.id+'/issues?parentId='+root.id)).data.items.length,1);
}));
test('labels and visible member search reach later records while hiding ungranted guests',()=>fixture(async({server,user,org,project,options,request})=>{
  const db=server.ctx.db,time=server.ctx.now();
  server.ctx.transaction(()=>{
    for(let n=0;n<212;n++){
      const id='member-'+String(n).padStart(3,'0');
      db.prepare('INSERT INTO users (id,email,name,password_hash,created_at,updated_at) SELECT ?,?,?,password_hash,?,? FROM users WHERE id=?').run(id,id+'@example.test','Person '+String(n).padStart(3,'0'),time,time,user.id);
      db.prepare('INSERT INTO memberships (org_id,user_id,role,created_at,updated_at) VALUES (?,?,?,?,?)').run(org.id,id,n===211?'guest':'member',time,time);
      db.prepare('INSERT INTO labels VALUES (?,?,?,?,?,?)').run('label-'+n,project.id,'Label '+String(n).padStart(3,'0'),'#123456',time,time);
    }
  });
  const users=await options('users','&q=Person%20210');assert.equal(users.data.items[0].id,'member-210');assert.equal(users.data.total,1);
  assert.equal((await options('users','&q=Person%20211')).data.total,0);
  await request('POST','/projects/'+project.id+'/guests',{userId:'member-211'});
  assert.equal((await options('users','&id=member-211')).data.total,1);
  const label=await options('labels','&q=Label%20211');assert.equal(label.data.items[0].id,'label-211');
  const later=(await request('GET','/projects/'+project.id+'/labels?q=211')).data;assert.equal(later.items[0].id,'label-211');
}));
