  const cross=(await request('POST','/orgs/'+org.id+'/projects',{key:'LIMIT',name:'Restricted endpoint'})).data.project;
  const source=create({title:'Source'}),target=(await request('POST','/projects/'+cross.id+'/issues',{title:'Private target'})).data.issue;
  const relation=(await request('POST','/issues/'+source.id+'/relations',{kind:'relates',targetIssueId:target.id})).data.relation;
  const guest=server.agent(),person=(await guest('POST','/auth/signup',{name:'Guest reader',email:'relation-reader-depth@example.test',password:'correct-horse-battery'})).data.user;
  await request('POST','/orgs/'+org.id+'/members',{userId:person.id,role:'guest'});
  await request('POST','/projects/'+project.id+'/guests',{userId:person.id});await request('POST','/projects/'+cross.id+'/guests',{userId:person.id});
  assert.equal((await request('DELETE','/relations/'+relation.id)).status,200);
  const route='/activity?orgId='+org.id+'&issueId='+source.id+'&entityType=relation&action=deleted&limit=1';
  for(const issue of [source,target]){const visible=await guest('GET','/activity?orgId='+org.id+'&issueId='+issue.id+'&entityType=relation&action=deleted&limit=1');assert.equal(visible.status,200);assert.equal(visible.data.items.length,1);assert.equal(visible.data.items[0].after,null);}
  assert.equal((await request('DELETE','/projects/'+cross.id+'/guests/'+person.id)).status,200);
  const denied=await guest('GET',route);assert.equal(denied.status,200);assert.deepEqual(denied.data.items,[]);assert.equal(denied.data.nextCursor,null);
